{ printf -- "-- setup.sql\n-- FLO Onboarding Portal: complete database setup. Paste into the Supabase SQL editor and click Run.\n-- This is supabase/migrations/0001..%s combined, in order. Safe to run more than once.\n-- Do not edit by hand: edit the migrations and re-combine them.\n\n" "$(ls supabase/migrations | tail -1 | cut -c1-4)"; for f in supabase/migrations/*.sql; do printf -- "-- ===========================================================================\n-- %s\n-- ===========================================================================\n\n" "$(basename $f)"; cat $f; printf "\n"; done; } > supabase/setup.sql
